-- SQL Migration Script for Get Access (Supabase)
-- Run this in the Supabase SQL Editor: https://supabase.com/dashboard/project/ufgirrelsprafqwucifb/sql/new

-- 1. Ensure table structure exists
CREATE TABLE IF NOT EXISTS public.app_settings (
  id TEXT PRIMARY KEY,
  telegram_group_url TEXT NOT NULL,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.videos (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL,
  description TEXT,
  price NUMERIC NOT NULL DEFAULT 5,
  video_url TEXT NOT NULL,
  thumbnail_url TEXT,
  duration TEXT,
  category TEXT DEFAULT 'Geral',
  views_count INTEGER DEFAULT 0,
  created_by UUID,
  is_published BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable Row Level Security (RLS) with public read access
ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'videos' AND policyname = 'Allow public read access to videos'
  ) THEN
    CREATE POLICY "Allow public read access to videos" ON public.videos FOR SELECT USING (true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'app_settings' AND policyname = 'Allow public read access to app_settings'
  ) THEN
    CREATE POLICY "Allow public read access to app_settings" ON public.app_settings FOR SELECT USING (true);
  END IF;
END
$$;

